daily_review.source_review_sql:
WITH rows AS(SELECT r FROM population_top3000_202608_202609_v1.pipeline_event e CROSS JOIN LATERAL jsonb_array_elements(details->'rows')r WHERE event_id=86479),refs AS(SELECT rows.r,x.kind,x.c FROM rows CROSS JOIN LATERAL (VALUES('current',r->'current_correction'),('previous',r->'previous_correction')) x(kind,c) WHERE x.c<>'null'::jsonb)
SELECT clock_timestamp() checked_at,count(*) links,count(*) FILTER(WHERE b.source_row IS NULL OR b.provider_close IS DISTINCT FROM (c->>'raw_close')::numeric OR encode(b.raw_record_sha256,'hex') IS DISTINCT FROM c->>'raw_record_sha256' OR s.source_sha256 IS DISTINCT FROM c->>'daily_source_sha256') source_errors
FROM refs LEFT JOIN population_top3000_202608_202609_v1.d02_daily_bar_v2 b ON b.source_day_id=(c->>'source_day_id')::bigint AND b.source_row=(c->>'source_row')::integer LEFT JOIN population_top3000_202608_202609_v1.d02_daily_source_v2 s ON s.source_day_id=b.source_day_id;
